import { getLogger } from '~/lib/log';
getLogger('variantSelector');
export default function variantSelector(product = {}) {
  return {
    product,
    optionNames: [],
    optionValues: {},
    optionSelections: {},

    init() {
      const variants = this.product?.variants || [];
      const names = new Set();
      const map = {};

      variants.forEach((v) => {
        (v.selectedOptions || []).forEach((o) => {
          if (!o.value || o.value === 'Default Title') {
            return;
          }

          names.add(o.name);
          map[o.name] ||= new Set();
          map[o.name].add(o.value);
        });
      });

      this.optionNames = Array.from(names);
      Object.keys(map).forEach((k) => {
        this.optionValues[k] = Array.from(map[k]).sort((a, b) => String(a).localeCompare(String(b)));
      });

      // Initialize default selection from first variant
      const first = variants.find((v) => v.selectedOptions?.length);
      if (first) {
        first.selectedOptions.forEach((o) => {
          this.optionSelections[o.name] = o.value;
        });
        this.selectVariantByOptions();
      }
    },

    isColor(value) {
      return /^#?[0-9A-Fa-f]{3,6}$/.test(value);
    },

    selectOption(name, value) {
      this.optionSelections[name] = value;
      this.selectVariantByOptions();
    },

    selectVariantByOptions() {
      const variants = this.product?.variants || [];
      const sel = variants.find((v) =>
        (v.selectedOptions || []).every((o) => this.optionSelections[o.name] === o.value),
      );

      this.product.selectedVariant = sel || null;
      this.product.displayPrice = sel?.price || null;
    },
  };
}
